CREATE TABLE qc_parents (parent_id int);
CREATE TABLE qc_children (child_id int, parent_id int);
INSERT INTO qc_parents VALUES (1), (2);
INSERT INTO qc_children VALUES (10, 1), (11, 3), (12, NULL), (13, 2), (14, 4);
SELECT c.child_id, c.parent_id
FROM qc_children c
WHERE c.parent_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM qc_parents p WHERE p.parent_id = c.parent_id)
ORDER BY c.child_id;

