guided.solution:
CREATE TABLE qc_payments (payment_id int, amount numeric(10,2), method text);
INSERT INTO qc_payments VALUES (1, 10.00, 'card'), (2, -3.00, NULL), (3, 5.00, 'cash'), (3, 5.00, 'cash'), (4, NULL, NULL), (5, -1.00, 'card');
SELECT check_name, violations FROM (
  SELECT 'missing method' AS check_name, COUNT(*) AS violations FROM qc_payments WHERE method IS NULL
  UNION ALL SELECT 'negative amount', COUNT(*) FROM qc_payments WHERE amount < 0
  UNION ALL SELECT 'duplicate payment_id', COUNT(*) FROM (SELECT payment_id FROM qc_payments GROUP BY payment_id HAVING COUNT(*) > 1) d
) r
ORDER BY check_name;

import sqlite3

conn = sqlite3.connect(":memory:")
conn.execute("CREATE TABLE t (id INTEGER PRIMARY KEY, amount REAL NOT NULL CHECK (amount >= 0))")
for row in [(1, 5.0), (1, 6.0), (2, -1.0), (3, None)]:
    try:
        conn.execute("INSERT INTO t VALUES (?, ?)", row)
        print("accepted")
    except sqlite3.IntegrityError:
        print("rejected")

