independent.solution:
CREATE TABLE qc_stock (sku text, qty int);
INSERT INTO qc_stock VALUES ('A', 5), ('B', 3), ('B', 9), ('C', NULL), ('D', -2), ('E', 7);
DELETE FROM qc_stock WHERE ctid NOT IN (SELECT MIN(ctid) FROM qc_stock GROUP BY sku);
DELETE FROM qc_stock WHERE qty IS NULL OR qty < 0;
ALTER TABLE qc_stock ADD CONSTRAINT qc_stock_pk PRIMARY KEY (sku);
ALTER TABLE qc_stock ADD CONSTRAINT qc_stock_qty_ck CHECK (qty >= 0);
SELECT sku, qty FROM qc_stock ORDER BY sku;

CREATE TABLE qc_a (id int CONSTRAINT qc_a_pk PRIMARY KEY);
CREATE TABLE qc_b (id int CONSTRAINT qc_b_pk PRIMARY KEY, a_id int CONSTRAINT qc_b_a_fk REFERENCES qc_a (id), qty int CONSTRAINT qc_b_qty_ck CHECK (qty > 0));
SELECT table_name, constraint_name, constraint_type
FROM information_schema.table_constraints
WHERE constraint_name ~ '_(pk|ck|fk)$' AND table_name LIKE 'qc\_%'
ORDER BY table_name, constraint_name;
